import re
from collections import deque
from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Sequence, Tuple


_SECTION_RE = re.compile(r"^\[(?P<id>[^\]]+)\]\s*$")
_CHOICE_RE = re.compile(r"^\s*(?P<num>\d+)\.\s*(?P<body>.+)$")


@dataclass(frozen=True)
class Node:
    id: str
    text: str
    speaker: str
    type: str  # "line" | "choice"


@dataclass(frozen=True)
class Edge:
    from_id: str
    to_id: str
    text: str


class ParseError(ValueError):
    pass


def _parse_line_with_optional_target(line: str) -> Tuple[str, str, Optional[str]]:
    """Return (speaker, text, target)."""
    line = line.strip()
    target: Optional[str] = None
    if "->" in line:
        left, right = line.rsplit("->", 1)
        target = right.strip()
        line = left.strip()

    speaker = ""
    text = line
    if ":" in line:
        speaker_part, text_part = line.split(":", 1)
        speaker = speaker_part.strip()
        text = text_part.strip()

    return speaker, text, target


def parse_script(text: str) -> Dict[str, Any]:
    """Parse a bracket-section dialogue script into a node/edge graph.

    Output format:
      {"nodes": [{"id","text","speaker","type"}],
       "edges": [{"from","to","text"}]}
    """

    sections: List[Tuple[str, List[str]]] = []
    current_id: Optional[str] = None
    current_lines: List[str] = []

    for raw in text.splitlines():
        m = _SECTION_RE.match(raw.strip())
        if m:
            if current_id is not None:
                sections.append((current_id, current_lines))
            current_id = m.group("id").strip()
            current_lines = []
            continue

        if current_id is None:
            if raw.strip() == "":
                continue
            raise ParseError(f"Content outside any section header: {raw!r}")

        current_lines.append(raw.rstrip("\n"))

    if current_id is not None:
        sections.append((current_id, current_lines))

    if not sections:
        raise ParseError("No sections found")

    nodes: Dict[str, Node] = {}
    edges: List[Edge] = []

    for section_id, lines in sections:
        if section_id in nodes:
            raise ParseError(f"Duplicate section id: {section_id}")

        content = [ln.strip() for ln in lines if ln.strip() != ""]
        if not content:
            nodes[section_id] = Node(id=section_id, text="", speaker="", type="line")
            continue

        is_choice = _CHOICE_RE.match(content[0]) is not None

        if is_choice:
            nodes[section_id] = Node(id=section_id, text="", speaker="", type="choice")
            for opt in content:
                m = _CHOICE_RE.match(opt)
                if not m:
                    raise ParseError(f"Mixed choice/non-choice lines in [{section_id}]: {opt!r}")
                body = m.group("body").strip()
                if "->" not in body:
                    raise ParseError(f"Choice missing '-> target' in [{section_id}]: {opt!r}")
                left, right = body.rsplit("->", 1)
                choice_text = left.strip()
                target = right.strip()
                edges.append(Edge(from_id=section_id, to_id=target, text=choice_text))
            continue

        combined = " ".join(content)
        speaker, line_text, target = _parse_line_with_optional_target(combined)
        nodes[section_id] = Node(id=section_id, text=line_text, speaker=speaker, type="line")
        if target:
            edges.append(Edge(from_id=section_id, to_id=target, text=""))

    defined_ids = set(nodes.keys())
    referenced_ids = {e.to_id for e in edges}
    missing = sorted(referenced_ids - defined_ids)
    if missing:
        # Common scripts omit a terminal [End] section; model it explicitly.
        for mid in missing:
            nodes[mid] = Node(id=mid, text="", speaker="", type="line")

    graph = {
        "nodes": [
            {"id": n.id, "text": n.text, "speaker": n.speaker, "type": n.type}
            for n in nodes.values()
        ],
        "edges": [{"from": e.from_id, "to": e.to_id, "text": e.text} for e in edges],
    }

    _validate_graph(graph, start_id=sections[0][0])
    return graph


def _validate_graph(graph: Dict[str, Any], start_id: str) -> None:
    node_ids = {n["id"] for n in graph.get("nodes", [])}
    if start_id not in node_ids:
        raise ParseError(f"Start node {start_id!r} not present")

    for e in graph.get("edges", []):
        if e["from"] not in node_ids:
            raise ParseError(f"Edge from missing node: {e}")
        if e["to"] not in node_ids:
            raise ParseError(f"Edge to missing node: {e}")

    adj: Dict[str, List[str]] = {nid: [] for nid in node_ids}
    for e in graph.get("edges", []):
        adj[e["from"]].append(e["to"])

    seen = set()
    q: deque[str] = deque([start_id])
    while q:
        cur = q.popleft()
        if cur in seen:
            continue
        seen.add(cur)
        for nxt in adj.get(cur, []):
            if nxt not in seen:
                q.append(nxt)

    unreachable = sorted(node_ids - seen)
    if unreachable:
        raise ParseError(f"Unreachable nodes from start {start_id!r}: {unreachable[:10]}")


def _dot_escape(s: str) -> str:
    return s.replace("\\", "\\\\").replace('"', '\\"')


def graph_to_dot(graph: Dict[str, Any]) -> str:
    nodes = graph.get("nodes", [])
    edges = graph.get("edges", [])

    node_type = {n["id"]: n.get("type", "") for n in nodes}
    node_label = {}
    for n in nodes:
        nid = n["id"]
        t = n.get("type", "")
        if t == "choice":
            label = nid
        else:
            speaker = n.get("speaker", "")
            text = n.get("text", "")
            label = nid
            if speaker or text:
                label = f"{nid}\\n{speaker + ': ' if speaker else ''}{text}"
        node_label[nid] = label

    lines = ["digraph Dialogue {", "  rankdir=LR;", "  node [fontname=Helvetica];"]
    for n in nodes:
        nid = n["id"]
        t = node_type.get(nid, "")
        shape = "diamond" if t == "choice" else "box"
        label = _dot_escape(node_label.get(nid, nid))
        lines.append(f'  "{_dot_escape(nid)}" [shape={shape}, label="{label}"];')

    for e in edges:
        frm = _dot_escape(e["from"])
        to = _dot_escape(e["to"])
        elabel = e.get("text", "")
        if elabel:
            lines.append(f'  "{frm}" -> "{to}" [label="{_dot_escape(elabel)}"];')
        else:
            lines.append(f'  "{frm}" -> "{to}";')

    lines.append("}")
    return "\n".join(lines)


def main() -> None:
    with open("/app/script.txt", "r", encoding="utf-8") as f:
        script_text = f.read()

    graph = parse_script(script_text)

    with open("/app/dialogue.json", "w", encoding="utf-8") as f:
        json.dump(graph, f, ensure_ascii=False, indent=2)
        f.write("\n")

    dot = graph_to_dot(graph)
    with open("/app/dialogue.dot", "w", encoding="utf-8") as f:
        f.write(dot)
        f.write("\n")


if __name__ == "__main__":
    main()
